import { writeFileSync } from 'node:fs'
import { publishedGuideFiles } from '../lib/guides/guide-files.mjs'

// Brief W1 §O: writes lib/guides/published.mjs, the list of published guides that the menu, sitemap, llms.txt and
// markdown copies read. Runs before `next build`; lib/guides/guides.ts then checks every published guide in full.

export function publishedModule(guides) {
  const entries = guides.map((guide) => `  { slug: ${JSON.stringify(guide.slug)}, title: ${JSON.stringify(guide.title)} },`)
  return [
    '// Generated by scripts/build-guide-index.mjs from content/guides; do not edit by hand. The build regenerates it before',
    '// `next build`, and tests/contracts/guides.test.ts fails if this committed copy is out of date. A plain module, so the',
    '// Edge middleware, next.config.mjs and the route lists can all import it.',
    `export const PUBLISHED_GUIDES = /** @type {{ slug: string, title: string }[]} */ ([${entries.length ? `\n${entries.join('\n')}\n` : ''}])`,
    '',
  ].join('\n')
}

if (import.meta.url === `file://${process.argv[1]?.replace(/\\/g, '/').replace(/^(?=[A-Za-z]:)/, '/')}`) {
  const guides = publishedGuideFiles().map(({ slug, title }) => ({ slug, title }))
  writeFileSync('lib/guides/published.mjs', publishedModule(guides))
  console.log(`Published guides: ${guides.length}`)
}
